package com.creditsense.domain;
import jakarta.persistence.*; import com.fasterxml.jackson.annotation.JsonIgnore; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="users") public class User { @Id private UUID id=UUID.randomUUID(); @Column(unique=true,nullable=false) private String email; @JsonIgnore @Column(name="password_hash",nullable=false) private String passwordHash; @Enumerated(EnumType.STRING) private Role role; @Column(name="created_at") private Instant createdAt=Instant.now(); public User(){} public User(String e,String p,Role r){email=e;passwordHash=p;role=r;} public UUID getId(){return id;} public String getEmail(){return email;} public String getPasswordHash(){return passwordHash;} public Role getRole(){return role;} public void setEmail(String v){email=v;} public void setPasswordHash(String v){passwordHash=v;} public void setRole(Role v){role=v;} }
